# ================================================================
# Free IR 1.0 — Reference Interpreter
# IR → 실행 결과 (정확성 100% 목표, 속도 무관)
#
# 역할: IR의 의미 보존 증명
# 이후: codegen 결과와 diff 비교로 self-verification
#
# Day 1 수정:
#   - func_map을 env에 포함 → call이 IR 함수 호출 가능
#   - continue 키워드 제거 → phi 스킵을 flag로 처리
#   - alloca 크기를 inst["alloc_type"]["size"] 사용
#   - call 처리: builtin → IR func → extern stub 순서
# ================================================================

# ----------------------------------------------------------------
# 1. 실행 환경 (Environment)
# ----------------------------------------------------------------

fn interp_env(regs, memory, mem_ptr, call_stack, globals, func_map) {
  # regs       : { reg_name → value }      SSA 레지스터 값
  # memory     : [value, ...]               선형 메모리 (alloca 영역)
  # mem_ptr    : i64                        다음 할당 주소
  # call_stack : [frame, ...]               호출 스택 (미래용)
  # globals    : { name → value }           전역 심볼
  # func_map   : { name → ir_func }        모듈 내 함수 맵 (call 해소용)
  return {
    "regs":       regs,
    "memory":     memory,
    "mem_ptr":    mem_ptr,
    "call_stack": call_stack,
    "globals":    globals,
    "func_map":   func_map
  }
}

fn interp_env_fresh(globals, func_map) {
  return interp_env({}, [], 0, [], globals, func_map)
}

# 레지스터 읽기
fn env_get_reg(env, name) {
  v = env["regs"][name]
  if v == null { return 0 }
  return v
}

# 레지스터 쓰기 (func_map 유지)
fn env_set_reg(env, name, value) {
  new_regs = map_set(env["regs"], name, value)
  return {
    "regs":       new_regs,
    "memory":     env["memory"],
    "mem_ptr":    env["mem_ptr"],
    "call_stack": env["call_stack"],
    "globals":    env["globals"],
    "func_map":   env["func_map"]
  }
}

# 메모리 alloca (주소 반환, 타입 크기 사용)
fn env_alloca(env, size) {
  addr = env["mem_ptr"]
  # 최소 1슬롯 보장
  if size < 1 { size = 1 }
  new_ptr = addr + size
  new_mem = env["memory"]
  i = len(new_mem)
  while i < new_ptr {
    new_mem = append(new_mem, 0)
    i = i + 1
  }
  new_env = {
    "regs":       env["regs"],
    "memory":     new_mem,
    "mem_ptr":    new_ptr,
    "call_stack": env["call_stack"],
    "globals":    env["globals"],
    "func_map":   env["func_map"]
  }
  return { "addr": addr, "env": new_env }
}

# 메모리 load (주소 → 값)
fn env_load(env, addr) {
  mem = env["memory"]
  if addr < 0 or addr >= len(mem) { return 0 }
  return mem[addr]
}

# 메모리 store (주소 ← 값, func_map 유지)
fn env_store(env, addr, value) {
  mem = env["memory"]
  while len(mem) <= addr {
    mem = append(mem, 0)
  }
  mem[addr] = value
  return {
    "regs":       env["regs"],
    "memory":     mem,
    "mem_ptr":    env["mem_ptr"],
    "call_stack": env["call_stack"],
    "globals":    env["globals"],
    "func_map":   env["func_map"]
  }
}

# ----------------------------------------------------------------
# 2. 값(Value) 평가
# ----------------------------------------------------------------

fn interp_val(env, val) {
  k = val["kind"]

  if k == "const_int"   { return val["value"] }
  if k == "const_float" { return val["value"] }
  if k == "const_bool"  {
    if val["value"] { return 1 }
    return 0
  }
  if k == "const_null"  { return 0 }

  if k == "reg" {
    return env_get_reg(env, val["name"])
  }

  if k == "global_ref" {
    g = env["globals"][val["name"]]
    if g == null { return 0 }
    return g
  }

  return 0
}

# ----------------------------------------------------------------
# 3. Instruction 실행
# ----------------------------------------------------------------

fn interp_result_continue(env) {
  return { "signal": "continue", "env": env }
}

fn interp_result_branch(label, env) {
  return { "signal": "branch", "label": label, "env": env }
}

fn interp_result_return(value, env) {
  return { "signal": "return", "value": value, "env": env }
}

fn interp_inst(env, inst) {
  k = inst["kind"]

  # --- 산술/논리 ---
  if k == "binop" {
    lv = interp_val(env, inst["lhs"])
    rv = interp_val(env, inst["rhs"])
    op = inst["op"]
    result = 0

    if op == "add"  { result = lv + rv }
    if op == "sub"  { result = lv - rv }
    if op == "mul"  { result = lv * rv }
    if op == "div"  {
      if rv == 0 { result = 0 }
      else       { result = lv / rv }
    }
    if op == "rem"  {
      if rv == 0 { result = 0 }
      else       { result = lv % rv }
    }
    if op == "and"  { result = lv & rv }
    if op == "or"   { result = lv | rv }
    if op == "xor"  { result = lv ^ rv }
    if op == "shl"  { result = lv << rv }
    if op == "shr"  { result = lv >> rv }
    if op == "fadd" { result = lv + rv }
    if op == "fsub" { result = lv - rv }
    if op == "fmul" { result = lv * rv }
    if op == "fdiv" {
      if rv == 0.0 { result = 0.0 }
      else         { result = lv / rv }
    }

    env = env_set_reg(env, inst["result"], result)
    return interp_result_continue(env)
  }

  if k == "neg" {
    v = interp_val(env, inst["operand"])
    env = env_set_reg(env, inst["result"], 0 - v)
    return interp_result_continue(env)
  }

  # --- 비교 ---
  if k == "icmp" or k == "fcmp" {
    lv = interp_val(env, inst["lhs"])
    rv = interp_val(env, inst["rhs"])
    pred = inst["pred"]
    cmp = 0

    if pred == "eq"  or pred == "oeq" {
      if lv == rv { cmp = 1 } else { cmp = 0 }
    }
    if pred == "ne"  or pred == "one" {
      if lv != rv { cmp = 1 } else { cmp = 0 }
    }
    if pred == "lt"  or pred == "olt" or pred == "ult" {
      if lv < rv  { cmp = 1 } else { cmp = 0 }
    }
    if pred == "le"  or pred == "ole" or pred == "ule" {
      if lv <= rv { cmp = 1 } else { cmp = 0 }
    }
    if pred == "gt"  or pred == "ogt" or pred == "ugt" {
      if lv > rv  { cmp = 1 } else { cmp = 0 }
    }
    if pred == "ge"  or pred == "oge" or pred == "uge" {
      if lv >= rv { cmp = 1 } else { cmp = 0 }
    }

    env = env_set_reg(env, inst["result"], cmp)
    return interp_result_continue(env)
  }

  # --- 메모리 ---
  if k == "alloca" {
    # 타입 크기 사용 (Phase 1: 슬롯 단위, 최소 1)
    size = inst["alloc_type"]["size"]
    if size == null or size == 0 { size = 1 }
    r = env_alloca(env, size)
    env = env_set_reg(r["env"], inst["result"], r["addr"])
    return interp_result_continue(env)
  }

  if k == "load" {
    ptr = interp_val(env, inst["ptr"])
    value = env_load(env, ptr)
    env = env_set_reg(env, inst["result"], value)
    return interp_result_continue(env)
  }

  if k == "store" {
    ptr = interp_val(env, inst["ptr"])
    value = interp_val(env, inst["val"])
    env = env_store(env, ptr, value)
    return interp_result_continue(env)
  }

  if k == "gep" {
    base = interp_val(env, inst["ptr"])
    idx  = interp_val(env, inst["idx"])
    # elem_type 크기 기반 stride (Phase 1: size 필드 사용)
    stride = inst["elem_type"]["size"]
    if stride == null or stride == 0 { stride = 1 }
    addr = base + idx * stride
    env = env_set_reg(env, inst["result"], addr)
    return interp_result_continue(env)
  }

  # --- 타입 변환 ---
  if k == "cast" {
    v = interp_val(env, inst["val"])
    op = inst["op"]
    result = v

    if op == "trunc" {
      to_name = inst["to_type"]["name"]
      if to_name == "i8"  or to_name == "u8"  { result = v & 0xFF }
      if to_name == "i16" or to_name == "u16" { result = v & 0xFFFF }
      if to_name == "i32" or to_name == "u32" { result = v & 0xFFFFFFFF }
    }
    if op == "zext" or op == "sext" or op == "fpext" or op == "fptrunc" {
      result = v
    }
    if op == "fptosi"  { result = int(v) }
    if op == "sitofp"  { result = float(v) }
    if op == "bitcast" or op == "ptrtoint" or op == "inttoptr" {
      result = v
    }

    env = env_set_reg(env, inst["result"], result)
    return interp_result_continue(env)
  }

  # --- 함수 호출 ---
  # 순서: 1) builtin  2) IR 함수  3) extern stub  4) 경고 후 0
  if k == "call" {
    callee = inst["callee"]
    args = inst["args"]
    arg_vals = []
    i = 0
    while i < len(args) {
      arg_vals = append(arg_vals, interp_val(env, args[i]))
      i = i + 1
    }

    callee_name = ""
    if callee["kind"] == "global_ref" { callee_name = callee["name"] }
    if callee["kind"] == "reg"        { callee_name = env_get_reg(env, callee["name"]) }

    ret_val = 0

    # 1) builtin
    if interp_is_builtin(callee_name) {
      ret_val = interp_builtin(callee_name, arg_vals)
    } else {
      # 2) IR 함수 (func_map에서 조회)
      func_map = env["func_map"]
      ir_func  = func_map[callee_name]
      if ir_func != null {
        ret_val = interp_function(ir_func, arg_vals, env["globals"], func_map)
      } else {
        # 3) extern stub: 경고 없이 0 반환 (Phase 1)
        ret_val = 0
      }
    }

    if inst["result"] != "" {
      env = env_set_reg(env, inst["result"], ret_val)
    }
    return interp_result_continue(env)
  }

  # --- 제어 흐름 ---
  if k == "br" {
    return interp_result_branch(inst["target"], env)
  }

  if k == "br_cond" {
    cond = interp_val(env, inst["cond"])
    if cond != 0 {
      return interp_result_branch(inst["true_label"], env)
    }
    return interp_result_branch(inst["false_label"], env)
  }

  if k == "ret" {
    value = interp_val(env, inst["val"])
    return interp_result_return(value, env)
  }

  if k == "ret_void" {
    return interp_result_return(0, env)
  }

  # --- Phi --- (interp_block에서 선처리, 여기선 pass)
  if k == "phi" {
    return interp_result_continue(env)
  }

  # 알 수 없는 instruction
  return interp_result_continue(env)
}

# ----------------------------------------------------------------
# 4. Basic Block 실행
# ----------------------------------------------------------------

fn interp_block(env, block, prev_label) {
  insts = block["instructions"]
  n = len(insts)

  # Pass 1: phi 먼저 처리 (SSA 의미론: 모든 phi를 동시에 평가)
  # phi 결과를 임시 저장 후 일괄 적용 (동시 평가 보장)
  phi_results = []
  phi_names   = []
  i = 0
  while i < n {
    inst = insts[i]
    if inst["kind"] == "phi" {
      phi_val = interp_phi(env, inst, prev_label)
      phi_results = append(phi_results, phi_val)
      phi_names   = append(phi_names,   inst["result"])
    }
    i = i + 1
  }
  # phi 결과 일괄 적용
  i = 0
  while i < len(phi_names) {
    env = env_set_reg(env, phi_names[i], phi_results[i])
    i = i + 1
  }

  # Pass 2: phi 제외 나머지 instruction 순차 실행
  i = 0
  while i < n {
    inst = insts[i]
    # phi는 이미 처리됨 — skip (continue 키워드 없이 flag 사용)
    is_phi = (inst["kind"] == "phi")
    if not is_phi {
      r = interp_inst(env, inst)
      env = r["env"]

      if r["signal"] == "branch" {
        return { "signal": "branch", "label": r["label"], "env": env }
      }
      if r["signal"] == "return" {
        return { "signal": "return", "value": r["value"], "env": env }
      }
    }
    i = i + 1
  }

  # terminator 없이 끝남 (비정상 IR)
  return { "signal": "return", "value": 0, "env": env }
}

fn interp_phi(env, phi_inst, prev_label) {
  incoming = phi_inst["incoming"]
  i = 0
  while i < len(incoming) {
    entry = incoming[i]
    if entry["block"] == prev_label {
      return interp_val(env, entry["val"])
    }
    i = i + 1
  }
  return 0
}

# ----------------------------------------------------------------
# 5. 함수 실행
# ----------------------------------------------------------------

fn interp_function(func, arg_vals, globals, func_map) {
  # callee 전용 env 생성 (독립 레지스터 + 스택)
  env = interp_env_fresh(globals, func_map)

  # 파라미터 바인딩 → 레지스터에 직접
  params = func["params"]
  i = 0
  while i < len(params) and i < len(arg_vals) {
    p_name = params[i]["name"]
    env = env_set_reg(env, p_name, arg_vals[i])
    i = i + 1
  }

  # 블록 맵 구성 { label → block }
  block_map = {}
  blocks = func["blocks"]
  i = 0
  while i < len(blocks) {
    b = blocks[i]
    block_map = map_set(block_map, b["label"], b)
    i = i + 1
  }

  # 실행 루프
  current_label = "entry"
  prev_label    = ""
  max_steps     = 100000   # 무한 루프 방지 (루프 많은 경우 대비)

  step = 0
  while step < max_steps {
    block = block_map[current_label]
    if block == null {
      return 0
    }

    r = interp_block(env, block, prev_label)
    env = r["env"]

    if r["signal"] == "return" {
      return r["value"]
    }

    if r["signal"] == "branch" {
      prev_label    = current_label
      current_label = r["label"]
    }

    step = step + 1
  }

  return 0
}

# ----------------------------------------------------------------
# 6. 내장 함수 (builtin)
# ----------------------------------------------------------------

fn interp_is_builtin(name) {
  if name == "println"  { return true }
  if name == "print"    { return true }
  if name == "str"      { return true }
  if name == "int"      { return true }
  if name == "float"    { return true }
  if name == "len"      { return true }
  if name == "append"   { return true }
  if name == "abs"      { return true }
  if name == "max"      { return true }
  if name == "min"      { return true }
  if name == "printf"   { return true }   # extern stub
  if name == "malloc"   { return true }   # extern stub
  if name == "free"     { return true }   # extern stub
  return false
}

fn interp_builtin(name, args) {
  if name == "println" {
    if len(args) > 0 { println(args[0]) }
    else             { println("") }
    return 0
  }

  if name == "print" {
    if len(args) > 0 { print(args[0]) }
    return 0
  }

  if name == "str" {
    if len(args) > 0 { return str(args[0]) }
    return ""
  }

  if name == "int" {
    if len(args) > 0 { return int(args[0]) }
    return 0
  }

  if name == "float" {
    if len(args) > 0 { return float(args[0]) }
    return 0.0
  }

  if name == "len" {
    if len(args) > 0 { return len(args[0]) }
    return 0
  }

  if name == "append" {
    if len(args) >= 2 { return append(args[0], args[1]) }
    return args[0]
  }

  if name == "abs" {
    v = args[0]
    if v < 0 { return 0 - v }
    return v
  }

  if name == "max" {
    if args[0] > args[1] { return args[0] }
    return args[1]
  }

  if name == "min" {
    if args[0] < args[1] { return args[0] }
    return args[1]
  }

  # extern stubs
  if name == "printf" { return 0 }
  if name == "malloc" { return 0 }
  if name == "free"   { return 0 }

  return 0
}

# ----------------------------------------------------------------
# 7. 모듈 실행기 (진입점)
# ----------------------------------------------------------------

fn interp_module(ir_mod, entry_fn_name, args) {
  # 전역 변수 초기화
  globals = {}
  globs = ir_mod["globals"]
  i = 0
  while i < len(globs) {
    g = globs[i]
    globals = map_set(globals, g["name"], g["init"])
    i = i + 1
  }

  # 함수 맵 구성 (모든 함수 등록)
  func_map = {}
  fns = ir_mod["functions"]
  i = 0
  while i < len(fns) {
    f = fns[i]
    func_map = map_set(func_map, f["name"], f)
    i = i + 1
  }

  # 진입 함수 찾기
  entry = func_map[entry_fn_name]
  if entry == null {
    println("ERROR: entry function not found: " + entry_fn_name)
    return 0
  }

  # func_map을 함께 전달 → 재귀/상호 호출 가능
  return interp_function(entry, args, globals, func_map)
}

# ----------------------------------------------------------------
# 유틸
# ----------------------------------------------------------------

fn map_get(m, key) {
  if m == null { return null }
  v = m[key]
  if v == null { return null }
