// codegen 검증 테스트
// native 결과 == interp 결과 확인
package main

import (
	"fmt"
	"fir/src/codegen"
	"fir/src/interp"
	"fir/src/ir"
	"os"
	"os/exec"
	"strconv"
	"strings"
)

// ----------------------------------------------------------------
// native 실행: ELF 바이너리를 파일로 쓰고 실행
// ----------------------------------------------------------------

// execElf: ELF 바이너리를 실행하고 exit code 반환
// ARM64에서는 qemu-x86_64 사용
func execElf(elfBytes []byte) (int64, error) {
	f, err := os.CreateTemp("", "fir_*.elf")
	if err != nil { return 0, err }
	defer os.Remove(f.Name())
	f.Write(elfBytes)
	f.Close()
	os.Chmod(f.Name(), 0755)

	var cmd *exec.Cmd
	arch := getArch()
	if arch != "x86_64" {
		qemu, err2 := exec.LookPath("qemu-x86_64")
		if err2 != nil { return 0, fmt.Errorf("qemu-x86_64 not found (arch=%s)", arch) }
		cmd = exec.Command(qemu, f.Name())
	} else {
		cmd = exec.Command(f.Name())
	}

	err = cmd.Run()
	if err != nil {
		if ee, ok := err.(*exec.ExitError); ok {
			return int64(ee.ExitCode()), nil
		}
		return 0, err
	}
	return 0, nil
}

func runNative(mod *ir.Module, entryName string) (int64, error) {
	cm, err := codegen.CompileModule(mod)
	if err != nil { return 0, fmt.Errorf("compile: %w", err) }

	off, ok := cm.FuncOff[entryName]
	if !ok { return 0, fmt.Errorf("entry not found: %s", entryName) }

	elfBytes := codegen.BuildELFWithEntry(cm.Code, off)
	return execElf(elfBytes)
}

