}

func runNative(mod *ir.Module, entryName string) (int64, error) {
	cm, err := codegen.CompileModule(mod)
	if err != nil { return 0, fmt.Errorf("compile: %w", err) }

	off, ok := cm.FuncOff[entryName]
	if !ok { return 0, fmt.Errorf("entry not found: %s", entryName) }

	elfBytes := codegen.BuildELFWithEntry(cm.Code, off)
	return execElf(elfBytes)
}

