// fir — Free IR Platform
// 엔트리포인트 + 테스트 러너
package main

import (
	"fmt"
	"fir/src/ir"
	"fir/src/interp"
	"os"
)

// ----------------------------------------------------------------
// assert
// ----------------------------------------------------------------

var passed, failed int

func assertEq(label string, got, expected int64) {
	if got == expected {
		fmt.Printf("[PASS] %s\n", label)
		passed++
	} else {
		fmt.Printf("[FAIL] %s | got=%d expected=%d\n", label, got, expected)
		failed++
	}
}

// ----------------------------------------------------------------
// Test 1: 상수 반환
// fn const42() -> i64 { return 42 }
// ----------------------------------------------------------------

func testConstReturn() {
	fmt.Println("--- Test 1: const return ---")
	entry := ir.NewBlock("entry")
	entry.Add(ir.NewRet(ir.ConstInt(42, ir.I64())))

	fn := ir.NewFunction("const42", nil, ir.I64(), false)
	fn.AddBlock(entry)

	mod := ir.NewModule("t1")
	mod.AddFunction(fn)

	r, _ := interp.ExecModule(mod, "const42", nil)
	assertEq("const42() == 42", r.AsInt(), 42)
}

// ----------------------------------------------------------------
// Test 2: 덧셈
// fn add(a, b) { return a + b }
// ----------------------------------------------------------------

func testAdd() {
	fmt.Println("--- Test 2: add ---")
	params := []ir.Param{
		{Name: "a", Type: ir.I64()},
		{Name: "b", Type: ir.I64()},
	}
	entry := ir.NewBlock("entry")
	entry.Add(ir.NewBinop("add", "r0", ir.I64(), ir.Reg("a", ir.I64()), ir.Reg("b", ir.I64())))
	entry.Add(ir.NewRet(ir.Reg("r0", ir.I64())))

	fn := ir.NewFunction("add", params, ir.I64(), false)
	fn.AddBlock(entry)

	mod := ir.NewModule("t2")
	mod.AddFunction(fn)

	r, _ := interp.ExecModule(mod, "add", []interp.RVal{interp.RInt(10), interp.RInt(32)})
	assertEq("add(10,32) == 42", r.AsInt(), 42)
}

// ----------------------------------------------------------------
// Test 3: 조건 분기
// fn is_positive(x) { if x>0 return 1; return 0 }
// ----------------------------------------------------------------

func testBranch() {
	fmt.Println("--- Test 3: conditional branch ---")
	params := []ir.Param{{Name: "x", Type: ir.I64()}}

	entry := ir.NewBlock("entry")
	entry.Add(ir.NewICmp("gt", "c", ir.I64(), ir.Reg("x", ir.I64()), ir.ConstInt(0, ir.I64())))
	entry.Add(ir.NewBrCond(ir.Reg("c", ir.Bool()), "yes", "no"))

	yes := ir.NewBlock("yes")
	yes.Add(ir.NewRet(ir.ConstInt(1, ir.I64())))

	no := ir.NewBlock("no")
	no.Add(ir.NewRet(ir.ConstInt(0, ir.I64())))

	fn := ir.NewFunction("is_positive", params, ir.I64(), false)
	fn.AddBlock(entry); fn.AddBlock(yes); fn.AddBlock(no)

	mod := ir.NewModule("t3")
	mod.AddFunction(fn)

	r1, _ := interp.ExecModule(mod, "is_positive", []interp.RVal{interp.RInt(5)})
	r2, _ := interp.ExecModule(mod, "is_positive", []interp.RVal{interp.RInt(0)})
	r3, _ := interp.ExecModule(mod, "is_positive", []interp.RVal{interp.RInt(-3)})
	assertEq("is_positive(5)  == 1", r1.AsInt(), 1)
	assertEq("is_positive(0)  == 0", r2.AsInt(), 0)
	assertEq("is_positive(-3) == 0", r3.AsInt(), 0)
}

// ----------------------------------------------------------------
// Test 4: phi 노드
// fn abs_phi(x) { entry→neg/exit(phi) }
// ----------------------------------------------------------------

func testPhi() {
	fmt.Println("--- Test 4: phi node ---")
	params := []ir.Param{{Name: "x", Type: ir.I64()}}

	entry := ir.NewBlock("entry")
	entry.Add(ir.NewICmp("lt", "c", ir.I64(), ir.Reg("x", ir.I64()), ir.ConstInt(0, ir.I64())))
	entry.Add(ir.NewBrCond(ir.Reg("c", ir.Bool()), "neg", "exit"))

	neg := ir.NewBlock("neg")
	neg.Add(ir.NewBinop("sub", "neg_x", ir.I64(), ir.ConstInt(0, ir.I64()), ir.Reg("x", ir.I64())))
	neg.Add(ir.NewBr("exit"))

	exit := ir.NewBlock("exit")
	exit.Add(ir.NewPhi("r", ir.I64(), []ir.PhiIncoming{
		{Val: ir.Reg("x", ir.I64()), Block: "entry"},
		{Val: ir.Reg("neg_x", ir.I64()), Block: "neg"},
	}))
	exit.Add(ir.NewRet(ir.Reg("r", ir.I64())))

	fn := ir.NewFunction("abs_phi", params, ir.I64(), false)
	fn.AddBlock(entry); fn.AddBlock(neg); fn.AddBlock(exit)

	mod := ir.NewModule("t4")
	mod.AddFunction(fn)

	r1, _ := interp.ExecModule(mod, "abs_phi", []interp.RVal{interp.RInt(5)})
	r2, _ := interp.ExecModule(mod, "abs_phi", []interp.RVal{interp.RInt(-7)})
	r3, _ := interp.ExecModule(mod, "abs_phi", []interp.RVal{interp.RInt(0)})
	assertEq("abs_phi(5)  == 5", r1.AsInt(), 5)
	assertEq("abs_phi(-7) == 7", r2.AsInt(), 7)
	assertEq("abs_phi(0)  == 0", r3.AsInt(), 0)
}

// ----------------------------------------------------------------
// Test 5: alloca / load / store
// ----------------------------------------------------------------

func testMemory() {
	fmt.Println("--- Test 5: alloca/load/store ---")
	entry := ir.NewBlock("entry")
	entry.Add(ir.NewAlloca("ptr", ir.I64()))
	entry.Add(ir.NewStore(ir.I64(), ir.ConstInt(99, ir.I64()), ir.Reg("ptr", ir.Ptr(ir.I64()))))
	entry.Add(ir.NewLoad("v", ir.I64(), ir.Reg("ptr", ir.Ptr(ir.I64()))))
	entry.Add(ir.NewRet(ir.Reg("v", ir.I64())))

	fn := ir.NewFunction("mem_rw", nil, ir.I64(), false)
	fn.AddBlock(entry)

	mod := ir.NewModule("t5")
	mod.AddFunction(fn)

	r, _ := interp.ExecModule(mod, "mem_rw", nil)
	assertEq("mem_rw() == 99", r.AsInt(), 99)
}

// ----------------------------------------------------------------
// Test 6: while 루프 (sum 0..n-1)
// ----------------------------------------------------------------

func testWhile() {
	fmt.Println("--- Test 6: while loop ---")
	params := []ir.Param{{Name: "n", Type: ir.I64()}}
	ptrI := ir.Reg("pi", ir.Ptr(ir.I64()))
	ptrS := ir.Reg("ps", ir.Ptr(ir.I64()))

	entry := ir.NewBlock("entry")
	entry.Add(ir.NewAlloca("pi", ir.I64()))
	entry.Add(ir.NewAlloca("ps", ir.I64()))
	entry.Add(ir.NewStore(ir.I64(), ir.ConstInt(0, ir.I64()), ptrI))
	entry.Add(ir.NewStore(ir.I64(), ir.ConstInt(0, ir.I64()), ptrS))
	entry.Add(ir.NewBr("loop_cond"))

	cond := ir.NewBlock("loop_cond")
	cond.Add(ir.NewLoad("i_cur", ir.I64(), ptrI))
	cond.Add(ir.NewICmp("lt", "cmp", ir.I64(), ir.Reg("i_cur", ir.I64()), ir.Reg("n", ir.I64())))
	cond.Add(ir.NewBrCond(ir.Reg("cmp", ir.Bool()), "loop_body", "loop_exit"))

	body := ir.NewBlock("loop_body")
	body.Add(ir.NewLoad("s_cur", ir.I64(), ptrS))
	body.Add(ir.NewLoad("i_b", ir.I64(), ptrI))
	body.Add(ir.NewBinop("add", "s_new", ir.I64(), ir.Reg("s_cur", ir.I64()), ir.Reg("i_b", ir.I64())))
	body.Add(ir.NewStore(ir.I64(), ir.Reg("s_new", ir.I64()), ptrS))
	body.Add(ir.NewBinop("add", "i_new", ir.I64(), ir.Reg("i_b", ir.I64()), ir.ConstInt(1, ir.I64())))
	body.Add(ir.NewStore(ir.I64(), ir.Reg("i_new", ir.I64()), ptrI))
	body.Add(ir.NewBr("loop_cond"))

	exitB := ir.NewBlock("loop_exit")
	exitB.Add(ir.NewLoad("s_final", ir.I64(), ptrS))
	exitB.Add(ir.NewRet(ir.Reg("s_final", ir.I64())))

	fn := ir.NewFunction("sum_to", params, ir.I64(), false)
	fn.AddBlock(entry); fn.AddBlock(cond); fn.AddBlock(body); fn.AddBlock(exitB)

	mod := ir.NewModule("t6")
	mod.AddFunction(fn)

	r0, _  := interp.ExecModule(mod, "sum_to", []interp.RVal{interp.RInt(0)})
	r5, _  := interp.ExecModule(mod, "sum_to", []interp.RVal{interp.RInt(5)})
	r10, _ := interp.ExecModule(mod, "sum_to", []interp.RVal{interp.RInt(10)})
	assertEq("sum_to(0)  == 0",  r0.AsInt(), 0)
	assertEq("sum_to(5)  == 10", r5.AsInt(), 10)
	assertEq("sum_to(10) == 45", r10.AsInt(), 45)
}

// ----------------------------------------------------------------
// Test 7: 재귀 (factorial)
// ----------------------------------------------------------------

func testRecursive() {
	fmt.Println("--- Test 7: recursive factorial ---")
	params := []ir.Param{{Name: "n", Type: ir.I64()}}

	// entry: if n<=1 goto base else goto rec
	entry := ir.NewBlock("entry")
	entry.Add(ir.NewICmp("le", "c", ir.I64(), ir.Reg("n", ir.I64()), ir.ConstInt(1, ir.I64())))
	entry.Add(ir.NewBrCond(ir.Reg("c", ir.Bool()), "base", "rec"))

	// base: return 1
	base := ir.NewBlock("base")
	base.Add(ir.NewRet(ir.ConstInt(1, ir.I64())))

	// rec: return n * factorial(n-1)
	rec := ir.NewBlock("rec")
	rec.Add(ir.NewBinop("sub", "n1", ir.I64(), ir.Reg("n", ir.I64()), ir.ConstInt(1, ir.I64())))
	rec.Add(ir.NewCall("r", ir.I64(), ir.GlobalRef("factorial", ir.I64()), []*ir.Value{ir.Reg("n1", ir.I64())}))
	rec.Add(ir.NewBinop("mul", "res", ir.I64(), ir.Reg("n", ir.I64()), ir.Reg("r", ir.I64())))
	rec.Add(ir.NewRet(ir.Reg("res", ir.I64())))

	fn := ir.NewFunction("factorial", params, ir.I64(), false)
	fn.AddBlock(entry); fn.AddBlock(base); fn.AddBlock(rec)

	mod := ir.NewModule("t7")
	mod.AddFunction(fn)

	r1, _ := interp.ExecModule(mod, "factorial", []interp.RVal{interp.RInt(1)})
	r5, _ := interp.ExecModule(mod, "factorial", []interp.RVal{interp.RInt(5)})
	assertEq("factorial(1) == 1",   r1.AsInt(), 1)
	assertEq("factorial(5) == 120", r5.AsInt(), 120)
}

// ----------------------------------------------------------------
// Test 8: cast trunc
// ----------------------------------------------------------------

func testCast() {
	fmt.Println("--- Test 8: cast trunc ---")
	entry := ir.NewBlock("entry")
	entry.Add(ir.NewCast("trunc", "r", ir.I64(), ir.ConstInt(300, ir.I64()), ir.I8()))
	entry.Add(ir.NewRet(ir.Reg("r", ir.I8())))

	fn := ir.NewFunction("trunc_test", nil, ir.I8(), false)
	fn.AddBlock(entry)

	mod := ir.NewModule("t8")
	mod.AddFunction(fn)

	r, _ := interp.ExecModule(mod, "trunc_test", nil)
	assertEq("trunc(300) to i8 == 44", r.AsInt(), 44) // 300 & 0xFF = 44
}

// ----------------------------------------------------------------
// Test 9: 다중 함수 호출
// fn double(x) { return x*2 }
// fn quad(x)   { return double(double(x)) }
// ----------------------------------------------------------------

func testMultiFunc() {
	fmt.Println("--- Test 9: multi-function call ---")

	// double
	dParams := []ir.Param{{Name: "x", Type: ir.I64()}}
	dEntry := ir.NewBlock("entry")
	dEntry.Add(ir.NewBinop("mul", "r", ir.I64(), ir.Reg("x", ir.I64()), ir.ConstInt(2, ir.I64())))
	dEntry.Add(ir.NewRet(ir.Reg("r", ir.I64())))
	double := ir.NewFunction("double", dParams, ir.I64(), false)
	double.AddBlock(dEntry)

	// quad: double(double(x))
	qParams := []ir.Param{{Name: "x", Type: ir.I64()}}
	qEntry := ir.NewBlock("entry")
	qEntry.Add(ir.NewCall("r1", ir.I64(), ir.GlobalRef("double", ir.I64()), []*ir.Value{ir.Reg("x", ir.I64())}))
	qEntry.Add(ir.NewCall("r2", ir.I64(), ir.GlobalRef("double", ir.I64()), []*ir.Value{ir.Reg("r1", ir.I64())}))
	qEntry.Add(ir.NewRet(ir.Reg("r2", ir.I64())))
	quad := ir.NewFunction("quad", qParams, ir.I64(), false)
	quad.AddBlock(qEntry)

	mod := ir.NewModule("t9")
	mod.AddFunction(double)
	mod.AddFunction(quad)

	r, _ := interp.ExecModule(mod, "quad", []interp.RVal{interp.RInt(3)})
	assertEq("quad(3) == 12", r.AsInt(), 12)
}

// ----------------------------------------------------------------
// Test 10: IR 텍스트 출력 확인
// ----------------------------------------------------------------

func testIRText() {
	fmt.Println("--- Test 10: IR text output ---")
	params := []ir.Param{{Name: "x", Type: ir.I64()}}
	entry := ir.NewBlock("entry")
	entry.Add(ir.NewBinop("add", "r0", ir.I64(), ir.Reg("x", ir.I64()), ir.ConstInt(1, ir.I64())))
	entry.Add(ir.NewRet(ir.Reg("r0", ir.I64())))

	fn := ir.NewFunction("inc", params, ir.I64(), true)
	fn.AddBlock(entry)

	mod := ir.NewModule("text_test")
	mod.AddFunction(fn)

	text := mod.String()
	if len(text) > 0 {
		fmt.Println(text)
		fmt.Println("[PASS] IR text output")
		passed++
	} else {
		fmt.Println("[FAIL] IR text output empty")
		failed++
	}
}

// ----------------------------------------------------------------
// main
// ----------------------------------------------------------------

func main() {
	fmt.Println("fir — Free IR Interpreter Tests")
	fmt.Println("=================================")

	testConstReturn()
	testAdd()
	testBranch()
	testPhi()
	testMemory()
	testWhile()
	testRecursive()
	testCast()
	testMultiFunc()
	testIRText()

	fmt.Println("=================================")
	fmt.Printf("Results: %d/%d PASS\n", passed, passed+failed)

	if failed == 0 {
		fmt.Println()
		fmt.Println("IR SEMANTICS VERIFIED")
		fmt.Println("IR is an executable language.")
		fmt.Println("Ready for codegen.")
	}

	// codegen 테스트
	runCodegenTests()

	// irgen 테스트 (FL → IR)
	runIRGenTests()

	// optimizer 테스트 (Phase 3)
	runOptTests()

	// struct/GEP 테스트 (Phase 3.4)
	runStructTests()

	// RegAlloc 테스트 (Phase 3.6)
	runRATests()

	if failed > 0 {
		os.Exit(1)
	}
}

