func testCast() {
	fmt.Println("--- Test 8: cast trunc ---")
	entry := ir.NewBlock("entry")
	entry.Add(ir.NewCast("trunc", "r", ir.I64(), ir.ConstInt(300, ir.I64()), ir.I8()))
	entry.Add(ir.NewRet(ir.Reg("r", ir.I8())))

	fn := ir.NewFunction("trunc_test", nil, ir.I8(), false)
	fn.AddBlock(entry)

	mod := ir.NewModule("t8")
	mod.AddFunction(fn)

	r, _ := interp.ExecModule(mod, "trunc_test", nil)
	assertEq("trunc(300) to i8 == 44", r.AsInt(), 44) // 300 & 0xFF = 44
}

// ----------------------------------------------------------------
// Test 9: 다중 함수 호출
// fn double(x) { return x*2 }
// fn quad(x)   { return double(double(x)) }
// ----------------------------------------------------------------

func testMultiFunc() {
	fmt.Println("--- Test 9: multi-function call ---")

	// double
	dParams := []ir.Param{{Name: "x", Type: ir.I64()}}
	dEntry := ir.NewBlock("entry")
	dEntry.Add(ir.NewBinop("mul", "r", ir.I64(), ir.Reg("x", ir.I64()), ir.ConstInt(2, ir.I64())))
	dEntry.Add(ir.NewRet(ir.Reg("r", ir.I64())))
	double := ir.NewFunction("double", dParams, ir.I64(), false)
	double.AddBlock(dEntry)

	// quad: double(double(x))
	qParams := []ir.Param{{Name: "x", Type: ir.I64()}}
	qEntry := ir.NewBlock("entry")
	qEntry.Add(ir.NewCall("r1", ir.I64(), ir.GlobalRef("double", ir.I64()), []*ir.Value{ir.Reg("x", ir.I64())}))
	qEntry.Add(ir.NewCall("r2", ir.I64(), ir.GlobalRef("double", ir.I64()), []*ir.Value{ir.Reg("r1", ir.I64())}))
	qEntry.Add(ir.NewRet(ir.Reg("r2", ir.I64())))
	quad := ir.NewFunction("quad", qParams, ir.I64(), false)
	quad.AddBlock(qEntry)

	mod := ir.NewModule("t9")
	mod.AddFunction(double)
	mod.AddFunction(quad)

	r, _ := interp.ExecModule(mod, "quad", []interp.RVal{interp.RInt(3)})
	assertEq("quad(3) == 12", r.AsInt(), 12)
}

