	params := []ir.Param{{Name: "x", Type: ir.I64()}}
	entry := ir.NewBlock("entry")
	entry.Add(ir.NewBinop("add", "r0", ir.I64(), ir.Reg("x", ir.I64()), ir.ConstInt(1, ir.I64())))
